// Signed 32-bit hash: can return a negative number.
function hash32(key){ let h=0; for(let i=0;i<key.length;i++){ h=(h<<5)-h+key.charCodeAt(i); h=h|0; } return h; }
function shardFor(key, N){
  return hash32(key) % N; // BUG: negative hash -> negative index, out of [0, N)
}

