const SHARDS = 4;

// shard by created date so recent orders are easy to find
function shardForOrder(order) {
  const day = Math.floor(order.createdAt / 86400000); // days since epoch
  return day % SHARDS;
}

// cross-shard report: total revenue today
async function revenueToday(shards) {
  const today = Math.floor(Date.now() / 86400000);
  const s = shards[today % SHARDS];
  const r = await s.query('SELECT SUM(amount) AS total FROM orders WHERE day = $1', [today]);
  return r.total;
}
